/bin/zsh -lc "/opt/homebrew/bin/node --input-type=module <<'JS'
import assert from 'node:assert/strict';
import runQueue, { readLimit } from './dist/queue.js';
import { submit } from './dist/caller.js';
assert.equal(readLimit('0'), 3);
let release;
const pending = new Promise(resolve => { release = resolve; });
const pausedCalls = [];
const result = await submit([{id:'paused',priority:1}], async job => { pausedCalls.push(job.id); await pending; });
assert.equal(result, 'finished');
assert.deepEqual(pausedCalls, ['paused']);
console.log(JSON.stringify({probe:'paused caller and early completion', limit:readLimit('0'),result,started:pausedCalls,saveStillPending:true}));
release();
const jobs = [{id:'A',priority:3},{id:'B',priority:1},{id:'C',priority:2}];
const saved = [];
await runQueue(jobs, '2', async job => { saved.push(job.id); });
assert.deepEqual(jobs.map(j=>j.id), ['B','C','A']);
console.log(JSON.stringify({probe:'mutation',callerArray:jobs.map(j=>j.id)}));
const order = [];
await runQueue([{id:'A',priority:2},{id:'B',priority:1},{id:'C',priority:3}], '2', async job=>{order.push(job.id);});
assert.deepEqual(order,['B','A']);
console.log(JSON.stringify({probe:'execution order',actual:order,required:['A','B']}));
const failure = new Error('save failed');
const unhandled = [];
process.on('unhandledRejection', error => unhandled.push(error));
const started = [];
let rejected = false;
await runQueue([{id:'first',priority:1},{id:'later',priority:2}], '2', async job=>{started.push(job.id); if(job.id==='first') throw failure;}).catch(()=>{rejected=true;});
await new Promise(resolve=>setImmediate(resolve));
assert.equal(rejected,false);
assert.deepEqual(started,['first','later']);
assert.equal(unhandled[0],failure);
console.log(JSON.stringify({probe:'save failure',queueRejected:rejected,started,unhandled:unhandled.map(e=>e.message)}));
JS"

